use filmcraft_project::{Project,ItemId,ParamValue,Keyframe};use filmcraft_geom::Vec2;use filmcraft_time::Tick;use filmcraft_render::{render_sequence,RenderOptions};use serde_json::{Value,json};
const T:i64=254016000000;
fn main(){let args:Vec<_>=std::env::args().collect();let f:Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let masks:Value=serde_json::from_slice(&std::fs::read(&args[2]).unwrap()).unwrap();let mask=masks["cases"].as_array().unwrap().iter().find(|c|c["effect"]=="opacity"&&c["mask_mode"]=="Add"&&c["shape"]==2&&c["profile"]==1).unwrap()["document"]["project"]["items"]["6"]["kind"]["Sequence"]["video_tracks"][0]["items"][0]["effects"][0]["masks"].clone();let mut cases=vec![];
for profile in 0..3{for path in 0..3{for motion in 0..2{for meta in 0..4{for at in [T/4,T*5/4,T*9/4]{
 let mut doc=f["cases"][0]["document"].clone();doc["project"]["items"]["1"]["kind"]=json!({"Graphic":{"width":64,"height":48,"rate":{"num":24,"den":1}}});let seq=&mut doc["project"]["items"]["6"]["kind"]["Sequence"];seq["settings"]["width"]=json!(96);seq["settings"]["height"]=json!(64);let clip=&mut seq["video_tracks"][0]["items"][0];clip["source_in"]=json!(0);clip["duration"]=json!(4*T);clip["frame_hold"]=Value::Null;clip["speed"]=json!(1.);clip["reverse"]=json!(false);let mut effects=vec![];
 for index in 0..if profile==2{3}else{1}{let id=if profile==1||index==1{"graphic_text"}else{"graphic_shape"};let mut e=filmcraft_project::effect_defs().iter().find(|d|d.id==id).unwrap().instance();if id=="graphic_text"{e.params.get_mut("text").unwrap().value=ParamValue::Text("Ab Я".into());e.params.get_mut("size").unwrap().value=ParamValue::Float(12.);}else{e.params.get_mut("size").unwrap().value=ParamValue::Vec2(Vec2::new(26.,18.));e.params.get_mut("shape").unwrap().value=ParamValue::Choice(index%2);}
 e.params.get_mut("position").unwrap().keyframes=vec![Keyframe::new(Tick(0),ParamValue::Vec2(Vec2::new(17.+index as f64*7.,18.))),Keyframe::new(Tick(3*T),ParamValue::Vec2(Vec2::new(38.,29.+index as f64*3.)))];e.params.get_mut("rotation").unwrap().value=ParamValue::Float(13.);e.params.get_mut("fill_color").unwrap().value=ParamValue::Color([0.7,0.2,0.4,0.75]);let mut raw=serde_json::to_value(e).unwrap();raw["layer"]=json!({"uid":index+1});if profile==2&&index==2{raw["layer"]["pin"]=json!({"to":{"layer":2},"left":true,"top":true,"offsets":[-2.,-2.,0.,0.]});}effects.push(raw);}
 if motion==1{let mut e=filmcraft_project::effect_defs().iter().find(|d|d.id=="motion").unwrap().instance();e.params.get_mut("scale").unwrap().value=ParamValue::Float(85.);e.params.get_mut("rotation").unwrap().value=ParamValue::Float(17.);effects.push(serde_json::to_value(e).unwrap());}
 if path==1{effects.push(json!({"effect":"invert","enabled":true,"params":{"channel":{"value":{"Choice":0}},"blend":{"value":{"Float":15.}}},"masks":mask}));}
 if path==2{effects.push(json!({"effect":"opacity","enabled":true,"params":{"opacity":{"value":{"Float":75.}},"blend":{"value":{"Choice":0}}},"masks":mask}));}
 clip["effects"]=json!(effects);if meta==1{clip["graphic"]=json!({"intro":T/2,"outro":T/2,"designIn":T/4,"designDuration":3*T});}else if meta>1{clip["graphic"]=json!({"roll":{"mode":if meta==2{"roll"}else{"crawlLeft"},"startOffScreen":true,"endOffScreen":true,"preroll":T/4,"easeIn":T/4,"easeOut":T/4,"postroll":T/4}});}
 let p:Project=serde_json::from_value(doc["project"].clone()).unwrap();for scale in [1f32,0.5,0.25]{let out=render_sequence(&p,ItemId(6),Tick(at),RenderOptions{scale,working_output:true,..Default::default()},&|_|None);cases.push(json!({"document":doc,"sequence":6,"at":at,"scale":scale,"profile":profile,"path":path,"motion":motion,"meta":meta,"width":out.w,"height":out.h,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),"rgba":out.to_rgba8()}));}
}}}}}println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases}));}
